def k1_k2__ref(n):
    qc = QuantumCircuit(n)
    for i in range(0, n):
        qc.h(i)
    for i in range(0, n - 1):
        qc.cp(math.pi / 2, i + 1, i)
    for i in range(0, n - 2):
        qc.cp(math.pi / 4, i + 2, i)
    return qc


def k1_k2__st_shift(n):
    qc = QuantumCircuit(n)
    for j in range(1, n + 1):
        qc.h(j - 1)
    for j in range(1, n):
        qc.cp(math.pi / 2, j, j - 1)
    for j in range(1, n - 1):
        qc.cp(math.pi / 4, j + 1, j - 1)
    return qc


