def k1_k1__ref(n):
    qc = QuantumCircuit(n)
    for i in range(0, n):
        qc.h(i)
    for i in range(0, n - 1):
        qc.cp(math.pi / 2, i + 1, i)
    return qc


def k1_k1__st_shift(n):
    qc = QuantumCircuit(n)
    for j in range(1, n + 1):
        qc.h(j - 1)
    for j in range(1, n):
        qc.cp(math.pi / 2, j, j - 1)
    return qc


def k1_k1__st_helper(n):
    qc = QuantumCircuit(n)
    k1_k1__st_helper_layers(qc, n)
    return qc


def k1_k1__st_helper_layers(qc, n):
    for i in range(0, n):
        qc.h(i)
    for i in range(0, n - 1):
        qc.cp(math.pi / 2, i + 1, i)


def k1_k1__st_vector(n):
    qc = QuantumCircuit(n)
    qc.h(range(0, n))
    for i in range(0, n - 1):
        qc.cp(math.pi / 2, i + 1, i)
    return qc


