def k1_out_k2_swaps__ref(n):
    qc = QuantumCircuit(n)
    for i in range(n):
        qc.h(i)
        for d in (1, 2):
            if i + d < n:
                qc.cp(math.pi / 2 ** d, i + d, i)
    for i in range(n // 2):
        qc.swap(i, n - 1 - i)
    return qc


